#!/usr/bin/env node
'use strict';
// Metric facade and bounded streaming tests execute the shipped pure module.
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const M=require('../../src/v050/07_facades.js');
let passed=0;function test(name,run){run();passed++;console.log('OK '+name);}
const near=(a,b,t=1e-8)=>assert.ok(Math.abs(a-b)<t,`${a} != ${b}`);
const copy=x=>JSON.parse(JSON.stringify(x));
function building(id='IGN:one',x=0,z=0,extra={}){return{mesh:'prism',geoLayer:'building',baseY:48.2,height:12,pos:[x+10,54.2,z+8],rings:[[[x,z],[x+20,z],[x+20,z+16],[x,z+16],[x,z]]],geoProperties:{sourceId:id,nombre_d_etages:4,usage_1:'Résidentiel'},v046Tile:'cadastre:16:33700:24000',...extra};}
const documented={schemaVersion:1,source:'https://example.org/public-plan',license:'CC BY 4.0',attribution:'Plan public de test, source synthétique',acquiredAt:'2026-10-23',openings:[{type:'door',ringIndex:0,edgeIndex:0,offset:3.2,bottom:0,width:1.4,height:2.35},{type:'window',ringIndex:0,edgeIndex:0,offset:8.25,bottom:4.1,width:1.6,height:1.9}]};
test('Metric source rings and heights survive facade analysis unchanged',()=>{const b=building(),before=copy(b),d=M.describe(b);assert.deepEqual(b,before);assert.deepEqual(d.rings,b.rings);near(d.baseY,48.2);near(d.height,12);});
test('Declared IGN floor count includes ground floor with no added level',()=>{const d=M.describe(building());assert.equal(d.levels,4);assert.equal(d.levelHeight,3);assert.equal(d.levelsBasis,'source-declared');});
test('A guessed floor count never stretches or truncates the original envelope',()=>{const b=building('guess',0,0,{height:9.8,geoProperties:{}}),d=M.describe(b);near(d.height,9.8);near(d.levels*d.levelHeight,9.8);assert.equal(d.levelsBasis,'invented');});
test('Negative absolute ground elevations remain negative',()=>near(M.describe(building('negative',0,0,{baseY:-12.4})).baseY,-12.4));
test('Invalid polygons and non-finite metric data are rejected',()=>{assert.equal(M.describe(building('bad',0,0,{rings:[[[0,0],[1,NaN],[2,0]]]})),null);assert.equal(M.describe(building('bad',0,0,{baseY:Infinity})),null);assert.equal(M.describe(building('bad',0,0,{height:0})),null);});
test('Components of the same multi-polygon source keep distinct building IDs',()=>assert.notEqual(M.describe(building()).id,M.describe(building('IGN:one',30,0)).id));
test('A stable identity ignores ring winding and starting vertex',()=>{const a=building(),b=copy(a),ring=b.rings[0].slice(0,-1).reverse();b.rings=[ring.slice(2).concat(ring.slice(0,2))];b.rings[0].push(b.rings[0][0]);assert.equal(M.describe(a).id,M.describe(b).id);});
test('Source identity remains separately readable',()=>assert.equal(M.describe(building('BDTOPO:123')).sourceId,'BDTOPO:123'));
test('IGN cleabs keeps a durable building identity across WFS feature renumbering',()=>{const a=building('batiment.123'),b=building('batiment.987');a.geoProperties.cleabs=b.geoProperties.cleabs='BATIMENT000000012345';const da=M.describe(a),db=M.describe(b);assert.equal(da.id,db.id);assert.equal(da.stableSourceId,'BATIMENT000000012345');assert.equal(db.sourceId,'batiment.987');assert.notEqual(da.sourceId,db.sourceId);assert.deepEqual(M.facadePlan(a).openings,M.facadePlan(b).openings);});
test('Missing, blank and overlong durable keys fall back to the preserved source identifier',()=>{for(const value of[undefined,null,'','  ','a'.repeat(513),17]){const b=building('WFS:fallback');b.geoProperties.cleabs=value;const d=M.describe(b);assert.equal(d.stableSourceId,'WFS:fallback');assert.ok(d.id.startsWith('WFS:fallback:'));}});
test('Different components of one durable IGN object retain distinct visit identities',()=>{const a=building('batiment.123'),b=building('batiment.123',30,0);a.geoProperties.cleabs=b.geoProperties.cleabs='BATIMENT000000012345';assert.notEqual(M.describe(a).id,M.describe(b).id);assert.equal(M.describe(a).stableSourceId,M.describe(b).stableSourceId);});
test('Courtyard order does not affect stable identity',()=>{const a=building();a.rings.push([[2,2],[2,4],[4,4],[4,2],[2,2]],[[12,4],[12,7],[15,7],[15,4],[12,4]]);const b=copy(a);b.rings=[a.rings[0],a.rings[2],a.rings[1]];assert.equal(M.describe(a).id,M.describe(b).id);});
test('Undocumented commercial and industrial buildings use coherent authored types',()=>{assert.equal(M.style({usage_1:'Industriel'}),'industrial');assert.equal(M.style({usage_1:'Commercial et services'}),'commercial');assert.equal(M.style({nature:'Église'}),'religious');assert.equal(M.style({amenity:'school'}),'civic');});
test('Object creation dates are not treated as construction dates or measured facade style',()=>assert.deepEqual(M.facadePlan(building()).openings,M.facadePlan(building('IGN:one',0,0,{geoProperties:{sourceId:'IGN:one',nombre_d_etages:4,usage_1:'Résidentiel',date_creation:'1910-01-01'}})).openings));
test('Invented entrance candidates lie on outer edges with valid inside/outside samples',()=>{const b=building(),d=M.describe(b),doors=M.entrances(b);assert.equal(doors.length,4);for(const door of doors){assert.equal(door.provenance,'invented');assert.equal(door.source,null);assert.equal(door.ringIndex,0);assert.equal(M.inside(d.rings,door.inside[0],door.inside[2]),true);assert.equal(M.inside(d.rings,door.outside[0],door.outside[2]),false);near(door.center[1],b.baseY);near(Math.hypot(...door.tangent),1);near(Math.hypot(...door.normal),1);}});
test('Only one invented doorway is displayed before an accessible candidate is selected',()=>assert.equal(M.facadePlan(building()).openings.filter(o=>o.type==='door').length,1));
test('The facade doorway follows the accessible edge selected by the interior binder',()=>{const b=building(),candidate=M.entrances(b)[1];b.v050EntranceSelection=candidate;const p=M.facadePlan(b),door=p.openings.find(o=>o.type==='door');assert.equal(p.doors.length,1);assert.equal(p.doors[0].id,candidate.id);assert.equal(door.edgeIndex,candidate.edgeIndex);near(door.offset,candidate.offset);});
test('An invented upper-street doorway renders at the selected 5m storey without changing the source envelope',()=>{const b=building('slope',0,0,{height:10,geoProperties:{sourceId:'slope',nombre_d_etages:3}}),before=copy(b),candidate=M.entrances(b)[0];b.v050EntranceSelection={...candidate,elevationOffset:5,levelElevations:[0,5,7.5]};const plan=M.facadePlan(b),g=M.geometry(b),door=g.renderedOpenings.find(o=>o.type==='door');near(door.bottom,5);near(plan.doors[0].center[1],b.baseY+5);near(plan.doors[0].inside[1],b.baseY+5);assert.equal(door.edgeIndex,candidate.edgeIndex);assert.deepEqual(b.rings,before.rings);near(g.description.height,10);assert.equal(g.description.levels,3);});
test('Invented windows align with the same bounded floor elevations used by the sloping-street interior',()=>{const b=building('slope',0,0,{height:10,geoProperties:{sourceId:'slope',nombre_d_etages:3}});b.v050EntranceSelection={...M.entrances(b)[0],elevationOffset:5,levelElevations:[0,5,7.5]};const p=M.facadePlan(b);assert.deepEqual(p.levelElevations,[0,5,7.5]);for(const o of p.openings.filter(o=>o.type!=='door'))assert.ok([0,1,2].some(i=>o.bottom>=[0,5,7.5][i]&&o.bottom+o.height<=([0,5,7.5][i+1]??10)));});
test('Malformed or out-of-volume upper-street offsets never create a fake shifted entrance',()=>{for(const elevationOffset of[-1,NaN,Infinity,'5',10]){const b=building();b.v050EntranceSelection={...M.entrances(b)[0],elevationOffset};assert.equal(M.facadePlan(b).openings.some(o=>o.type==='door'),false);}});
test('A selected floor cannot move or resize an explicitly documented doorway',()=>{const b=building();b.geoProperties.facadeDocument=copy(documented);b.v050EntranceSelection={...M.entrances(b)[0],elevationOffset:5,height:1.85};const p=M.facadePlan(b),door=p.openings.find(o=>o.type==='door');near(door.bottom,documented.openings[0].bottom);near(door.height,2.35);near(p.doors[0].center[1],b.baseY);assert.equal(door.provenance,'documented');});
test('Low but physically inhabitable storeys retain a doorway instead of a proportion-based rejection',()=>{const b=building('low',0,0,{height:7,geoProperties:{sourceId:'low',nombre_d_etages:3}}),doors=M.entrances(b);assert.ok(doors.length>0);assert.ok(doors.every(d=>d.height>=1.85&&d.height<=7/3-.08+1e-7));const minimum=building('minimum',0,0,{height:1.95,geoProperties:{sourceId:'minimum',nombre_d_etages:1}});near(M.entrances(minimum)[0].height,1.87);});
test('Invented doorway height stays below its aligned storey ceiling',()=>{const b=building('slope-low',0,0,{height:8,geoProperties:{sourceId:'slope-low',nombre_d_etages:3}});b.v050EntranceSelection={...M.entrances(b)[0],elevationOffset:4.1,levelElevations:[0,4.1,6.05]};const p=M.facadePlan(b),door=p.openings.find(o=>o.type==='door');near(door.height,1.87);assert.ok(door.bottom+door.height<=6.05);});
test('A claimed selection cannot enlarge an invented door beyond its canonical metric height',()=>{const b=building();b.v050EntranceSelection={...M.entrances(b)[0],height:20};assert.equal(M.facadePlan(b).openings.some(o=>o.type==='door'),false);});
test('An explicitly unreachable building receives no invented access doorway',()=>{const b=building();b.v050EntranceSelection=null;assert.equal(M.facadePlan(b).openings.filter(o=>o.type==='door').length,0);});
test('Door placement survives source ring winding changes',()=>{const b=building(),reverse=copy(b);reverse.rings=reverse.rings.map(r=>r.slice().reverse());const a=M.entrances(b)[0],c=M.entrances(reverse)[0];assert.deepEqual(a.center,c.center);assert.deepEqual(a.outside,c.outside);assert.deepEqual(a.inside,c.inside);});
test('An uninhabitable sliver is not assigned a fake walkable entrance',()=>assert.equal(M.entrances(building('sliver',0,0,{rings:[[[0,0],[20,0],[20,.2],[0,.2],[0,0]]]})).length,0));
test('A low envelope is not given a door taller than its building',()=>assert.equal(M.entrances(building('shed',0,0,{height:1.6})).length,0));
test('Source courtyard edges point into the actual empty courtyard',()=>{const b=building();b.rings.push([[5,4],[5,12],[15,12],[15,4],[5,4]]);const d=M.describe(b);for(const e of M.edges(d).filter(e=>e.ringIndex===1)){const p=[(e.a[0]+e.b[0])/2,(e.a[1]+e.b[1])/2];assert.equal(M.inside(d.rings,p[0]+e.normal[0]*.1,p[1]+e.normal[1]*.1),false);assert.equal(M.inside(d.rings,p[0]-e.normal[0]*.1,p[1]-e.normal[1]*.1),true);}});
test('A documented doorway uses exact metres and public provenance',()=>{const b=building();b.geoProperties.facadeDocument=copy(documented);const door=M.entrances(b)[0];near(door.center[0],3.2+.7);near(door.center[2],0);near(door.width,1.4);near(door.height,2.35);assert.equal(door.provenance,'documented');assert.equal(door.source,documented.source);});
test('Documented window dimensions and offsets are never clamped to a generic bay',()=>{const b=building();b.geoProperties.facadeDocument=copy(documented);const p=M.facadePlan(b),window=p.openings.find(o=>o.type==='window'&&o.provenance==='documented');assert.deepEqual(window,{...documented.openings[1],provenance:'documented',source:documented.source});assert.equal(p.provenance,'mixed');});
test('A facade document without attribution is never presented as documentation',()=>{const b=building();b.geoProperties.facadeDocument={...copy(documented),attribution:''};assert.equal(M.describe(b).facadeDocument,null);assert.equal(M.entrances(b)[0].provenance,'invented');});
test('Unknown units and impossible documented dimensions cannot become metric openings',()=>{const b=building();b.geoProperties.facadeDocument=copy(documented);b.geoProperties.facadeDocument.openings[0].width='4 feet';assert.equal(M.describe(b).facadeDocument,null);b.geoProperties.facadeDocument=copy(documented);b.geoProperties.facadeDocument.openings[1].offset=200;assert.equal(M.facadePlan(b).openings.some(o=>o.provenance==='documented'&&o.type==='window'),false);});
test('A documented complete edge is not filled with invented windows',()=>{const b=building();b.geoProperties.facadeDocument={...copy(documented),completeEdges:[{ringIndex:0,edgeIndex:0}]};const p=M.facadePlan(b);assert.ok(p.openings.some(o=>o.provenance==='documented'&&o.edgeIndex===0));assert.equal(p.openings.some(o=>o.provenance==='invented'&&o.edgeIndex===0),false);assert.ok(p.openings.some(o=>o.provenance==='invented'&&o.edgeIndex!==0));});
test('A documented blind facade is not assigned an invented front entrance',()=>{const b=building();b.geoProperties.facadeDocument={...copy(documented),openings:[],completeEdges:[0,1,2,3].map(edgeIndex=>({ringIndex:0,edgeIndex}))};assert.equal(M.entrances(b).length,0);assert.equal(M.facadePlan(b).openings.length,0);});
test('An invented doorway cannot replace a known window on a partially documented edge',()=>{const b=building(),edge=M.entrances(b)[0].edgeIndex;b.geoProperties.facadeDocument={...copy(documented),openings:[{type:'window',ringIndex:0,edgeIndex:edge,offset:0,bottom:.3,width:16,height:1.5}]};assert.equal(M.entrances(b).some(o=>o.edgeIndex===edge),false);});
test('Inferred openings do not cover the source doorway or known windows',()=>{const b=building();b.geoProperties.facadeDocument=copy(documented);const p=M.facadePlan(b);for(const a of p.openings.filter(o=>o.provenance==='documented'))for(const o of p.openings.filter(o=>o.provenance==='invented'&&o.ringIndex===a.ringIndex&&o.edgeIndex===a.edgeIndex))assert.equal(a.offset<o.offset+o.width&&a.offset+a.width>o.offset&&a.bottom<o.bottom+o.height&&a.bottom+a.height>o.bottom,false);});
test('Facade generation is deterministic and does not mutate source geometry',()=>{const b=building(),before=copy(b);assert.deepEqual(M.geometry(b),M.geometry(b));assert.deepEqual(b,before);});
test('Facade meshes retain tile ownership and authored provenance for streaming',()=>{const g=M.geometry(building());assert.ok(g.draws.length>1);for(const d of g.draws){assert.equal(d.mesh,'geoSurface');assert.equal(d.v046Tile,'cadastre:16:33700:24000');assert.equal(d.v050Facade,true);assert.equal(d.facadeProvenance,'invented');assert.equal(d.sourceProvenance,null);}});
test('Every decorative triangle uses exact source edges and a declared small rendering offset',()=>{const b=building(),g=M.geometry(b),edges=M.edges(M.describe(b));for(const d of g.draws)for(const p of d.vertices){assert.ok(p[1]>=b.baseY-1e-7&&p[1]<=b.baseY+b.height+1e-7);assert.ok(edges.some(e=>{const x=p[0]-e.a[0],z=p[2]-e.a[1],along=x*e.tangent[0]+z*e.tangent[1],away=x*e.normal[0]+z*e.normal[1];return along>=-1e-7&&along<=e.length+1e-7&&away>=0&&away<=.0750001;}));}});
test('Courtyard facade decoration leaves the courtyard unfilled',()=>{const b=building();b.rings.push([[5,4],[5,12],[15,12],[15,4],[5,4]]);const g=M.geometry(b);assert.ok(g.draws.every(d=>d.vertices.every(p=>!(p[0]>5.08&&p[0]<14.92&&p[2]>4.08&&p[2]<11.92))));});
test('Generated faces index valid finite metric vertices',()=>{for(const d of M.geometry(building()).draws){assert.ok(d.vertices.every(p=>p.length===3&&p.every(Number.isFinite)));assert.ok(d.faces.every(f=>f.length===3&&f.every(i=>Number.isInteger(i)&&i>=0&&i<d.vertices.length)));}});
test('Geometry respects its triangle and quad budget without an empty-air collider',()=>{const b=building(),g=M.geometry(b,{maxQuads:32});assert.ok(g.quads<=32);assert.equal(g.draws.reduce((n,d)=>n+d.faces.length,0),g.quads*2);assert.equal(b.colliders,undefined);});
test('Low detail contains fewer triangles while keeping the metric source envelope',()=>{const b=building(),high=M.geometry(b,{detail:'high'}),low=M.geometry(b,{detail:'low'});assert.ok(low.quads<high.quads);assert.equal(low.description.height,high.description.height);assert.equal(low.description.levels,high.description.levels);});
test('Complex 200-level polygons are bounded before any window-object expansion',()=>{const ring=[];for(let i=0;i<4096;i++){const a=i/4096*Math.PI*2;ring.push([Math.cos(a)*3000,Math.sin(a)*3000]);}ring.push(ring[0]);const b=building('large',0,0,{rings:[ring],height:640,geoProperties:{sourceId:'large',nombre_d_etages:200}}),started=performance.now(),plan=M.facadePlan(b,{maxOpenings:24}),g=M.geometry(b,{maxQuads:64});assert.equal(plan.levels,200);assert.ok(plan.openings.length<=24);assert.ok(plan.detailCoverage.attempted<=96);assert.equal(plan.detailCoverage.budgeted,true);assert.ok(g.quads<=64);assert.ok(performance.now()-started<3000,'Bounded high-complexity plan took over 3s');});
test('A doorway remains visible when a complex source perimeter exhausts the facade panel budget',()=>{const ring=[];for(let i=0;i<300;i++){const a=i/300*Math.PI*2;ring.push([Math.cos(a)*100,Math.sin(a)*100]);}ring.push(ring[0]);const b=building('complex-door',0,0,{rings:[ring]}),doors=M.entrances(b);b.v050EntranceSelection=doors.at(-1);const g=M.geometry(b,{maxQuads:24}),door=g.renderedOpenings.find(o=>o.type==='door');assert.ok(door);assert.equal(door.edgeIndex,b.v050EntranceSelection.edgeIndex);assert.ok(g.quads<=24);});
test('Sparse facade sampling reaches upper levels without constructing every lower bay',()=>{const b=building('tower',0,0,{height:600,geoProperties:{sourceId:'tower',nombre_d_etages:200}}),p=M.facadePlan(b,{maxOpenings:24});assert.ok(p.openings.some(o=>o.bottom>550));assert.ok(p.openings.some(o=>o.bottom<20));assert.equal(p.levels,200);});
test('Spatial selection excludes distant city buildings before mesh generation',()=>{const draws=Array.from({length:1000},(_,i)=>building('source:'+i,i*50,0)),idx=new M.Index(draws),close=idx.around(5,5,75,5);assert.equal(idx.count,1000);assert.ok(close.length<=5);assert.ok(close.every(i=>i.distance<=75));assert.ok(close.every(i=>i.description.bounds.minX<100));});
test('Spatial buckets deduplicate a building spanning multiple cells',()=>{const b=building('wide',0,0,{rings:[[[0,0],[300,0],[300,300],[0,300],[0,0]]]}),idx=new M.Index([b]);assert.equal(idx.around(100,100,500,64).length,1);});
test('Large building bounds avoid unbounded spatial cell allocation',()=>{const b=building('huge',0,0,{rings:[[[0,0],[100000,0],[100000,100000],[0,100000],[0,0]]]}),idx=new M.Index([b]);assert.equal(idx.cells.size,0);assert.equal(idx.large.length,1);assert.equal(idx.around(100,100).length,1);});
test('Two components sharing one source ID both remain selectable',()=>{const idx=new M.Index([building(),building('IGN:one',30,0)]);assert.equal(idx.count,2);assert.equal(idx.around(10,0,100).length,2);});
test('Facade caches reuse exact geometry while unchanged',()=>{const cache=new M.Cache(),b=building(),a=cache.get(b),c=cache.get(b);assert.equal(a,c);assert.equal(cache.hits,1);assert.equal(cache.builds,1);});
test('A source height, footprint or documented-opening edit invalidates the cached mesh',()=>{const cache=new M.Cache(),b=building(),a=cache.get(b);b.height=15;assert.notEqual(cache.get(b),a);const c=cache.get(b);b.geoProperties.facadeDocument=copy(documented);assert.notEqual(cache.get(b),c);});
test('Choosing another accessible wall invalidates facade geometry without changing the source polygon',()=>{const cache=new M.Cache(),b=building(),before=copy(b.rings),a=cache.get(b);b.v050EntranceSelection=M.entrances(b)[1];const g=cache.get(b);assert.notEqual(g,a);assert.equal(g.renderedOpenings.find(o=>o.type==='door').edgeIndex,b.v050EntranceSelection.edgeIndex);assert.deepEqual(b.rings,before);});
test('An upper-street elevation invalidates the exact facade cache and preserves source XY',()=>{const b=building(),cache=new M.Cache();b.v050EntranceSelection=M.entrances(b)[0];const a=cache.get(b);b.v050EntranceSelection={...b.v050EntranceSelection,elevationOffset:5};const g=cache.get(b),before=a.renderedOpenings.find(o=>o.type==='door'),after=g.renderedOpenings.find(o=>o.type==='door');assert.notEqual(a,g);near(before.bottom,0);near(after.bottom,5);near(before.offset,after.offset);assert.equal(before.edgeIndex,after.edgeIndex);});
test('LRU ownership stays below both count and estimated byte budgets',()=>{const cache=new M.Cache(170000,2);for(let i=0;i<10;i++)cache.get(building('cache:'+i),{maxQuads:128});assert.ok(cache.bytes<=cache.maxBytes);assert.ok(cache.entries.size<=2);assert.ok(cache.evictions>0);});
test('A single oversized facade is not retained or allowed to evict valid entries endlessly',()=>{const cache=new M.Cache(16,2),g=cache.get(building());assert.ok(g.draws.length>0);assert.equal(cache.entries.size,0);assert.equal(cache.bytes,0);});
test('Clearing facade ownership is idempotent',()=>{const cache=new M.Cache();cache.get(building());cache.clear();cache.clear();assert.equal(cache.entries.size,0);assert.equal(cache.bytes,0);});

// Real IGN footprint, projected with the shipped Lambert93 transform. This is
// source topology coverage, not evidence of surveyed doors, windows or occupancy.
