function allPages(b,limit=7){let cursor=0,pages=0,openings=[],last;do{last=M.facadePage(b,{cursor,limit});assert.ok(last.nextCursor>=cursor);assert.ok(last.openings.length<=limit);assert.ok(last.scanned<=Math.min(16384,limit*8));openings.push(...last.openings);cursor=last.nextCursor;assert.ok(++pages<100000,'Pagination failed to terminate');}while(!last.done);return{openings,pages,inventory:last.inventory};}
function assertOnSource(b,g){const es=M.edges(M.describe(b));for(const d of g.draws)for(const p of d.vertices){assert.ok(p[1]>=b.baseY-1e-7&&p[1]<=b.baseY+b.height+1e-7);assert.ok(es.some(e=>{const x=p[0]-e.a[0],z=p[2]-e.a[1],along=x*e.tangent[0]+z*e.tangent[1],away=x*e.normal[0]+z*e.normal[1];return along>=-1e-7&&along<=e.length+1e-7&&away>=-1e-7&&away<=.0750001;}),'A curved fragment left its source segment');}}
test('Explicit IGN usage overrides its ambiguous industrial/agricultural/commercial nature',()=>{for(const[usage,expected]of[['Commercial et services','commercial'],['Résidentiel','residential'],['Sportif','civic']]){const d=M.describe(building('usage',0,0,{geoProperties:{usage_1:usage,nature:'Industriel, agricole ou commercial'}}));assert.equal(d.style,expected);assert.equal(d.styleBasis,'usage_1');}});
test('A linked architecture use is a fallback after known source usages',()=>{assert.equal(M.style({usage_1:'Indifférencié',nature:'Indifférenciée',architectureUse:'Religieux'}),'religious');assert.equal(M.style({usage_1:'Commercial et services',architectureUse:'Religieux'}),'commercial');assert.equal(M.style({usage_1:'Indifférencié',usage_2:'Résidentiel',architectureUse:'Religieux'}),'residential');});
test('Unknown functional-volume levels are inferred from typology without adding apartment stacks',()=>{for(const[nature,height,type]of[['Religieux',45.8,'nave'],['Tribune',67.3,'grandstand'],['Serre',8,'greenhouse'],['Silo',40,'technical-tower'],['Hangar',18,'open-hall'],['Annexe',5,'annexe']]){const b=building('function',0,0,{height,geoProperties:{nature,nombre_d_etages:null}}),d=M.describe(b);assert.equal(d.typology,type);assert.equal(d.levels,1);assert.equal(d.levelInferenceBasis,'invented-functional-volume');near(d.height,height);}});
test('A declared one-storey 143.9m volume keeps its exact source levels and height',()=>{const d=M.describe(building('batiment.26019993',0,0,{height:143.9,geoProperties:{nature:'Industriel, agricole ou commercial',usage_1:'Commercial et services',nombre_d_etages:1}}));assert.equal(d.style,'commercial');assert.equal(d.levels,1);assert.equal(d.levelInferenceBasis,'source-declared');near(d.levelHeight,143.9);});
test('Nave clerestory and hall registers remain facade openings within one functional storey',()=>{for(const nature of['Religieux','Hangar']){const b=building('register',0,0,{height:45.8,geoProperties:{nature}}),p=M.facadePlan(b,{maxOpenings:4096}),windows=p.openings.filter(o=>o.type==='window');assert.equal(p.levels,1);assert.deepEqual(p.levelElevations,[0]);assert.equal(p.openingInventory.windowRegisters,2);assert.ok(windows.some(o=>o.bottom>30));assert.ok(windows.some(o=>o.bottom<3));for(const o of windows)assert.ok(o.bottom+o.height<45.8);}});
test('A technical tower does not receive an invented generic apartment-window grid',()=>{const p=M.facadePlan(building('silo',0,0,{height:40,geoProperties:{nature:'Silo'}}));assert.equal(p.openingInventory.windowRegisters,0);assert.equal(p.openings.some(o=>o.type==='window'),false);assert.equal(p.openings.filter(o=>o.type==='door').length,1);});
test('Long facade inventory keeps metric bay spacing beyond the former 160-column ceiling',()=>{const b=building('long',0,0,{rings:[[[0,0],[4000,0],[4000,20],[0,20],[0,0]]],height:12,geoProperties:{usage_1:'Industriel',nombre_d_etages:3}});b.v050EntranceSelection=null;const pages=allPages(b,113),perLong=Math.floor(4000/4.8),perShort=Math.floor(20/4.8);assert.equal(pages.inventory.potentialOpenings,2*(perLong+perShort)*3);assert.equal(pages.openings.length,pages.inventory.potentialOpenings);assert.equal(new Set(pages.openings.map(o=>JSON.stringify(o))).size,pages.openings.length);for(let edgeIndex=0;edgeIndex<4;edgeIndex++){const ws=pages.openings.filter(o=>o.edgeIndex===edgeIndex);assert.equal(ws.length,(edgeIndex%2?perShort:perLong)*3);if(edgeIndex%2===0){const row=ws.filter(o=>o.bottom===ws[0].bottom).sort((a,b)=>a.offset-b.offset);near(row[1].offset-row[0].offset,4000/perLong);assert.ok(row.at(-1).offset>3990);}}});
test('Facade cursor pages include all supported documentary openings without changing measured data',()=>{const b=building('document-grid',0,0,{rings:[[[0,0],[5000,0],[5000,16],[0,16],[0,0]]]});b.v050EntranceSelection=null;b.geoProperties.facadeDocument={...copy(documented),openings:Array.from({length:2048},(_,i)=>({type:'window',ringIndex:0,edgeIndex:0,offset:i*2,bottom:4.1,width:.6,height:1.2}))};const before=copy(b),pages=allPages(b,31),known=pages.openings.filter(o=>o.provenance==='documented');assert.equal(known.length,2048);assert.deepEqual(known,b.geoProperties.facadeDocument.openings.map(o=>({...o,provenance:'documented',source:documented.source})));assert.deepEqual(pages.inventory.documentedCoverage,{declared:2048,accepted:2048,rejected:0});assert.deepEqual(b,before);});
test('Invalid facade cursors and page sizes cannot expand an unbounded page',()=>{const b=building();for(const cursor of[-1,.5,Infinity,Number.MAX_SAFE_INTEGER])assert.throws(()=>M.facadePage(b,{cursor}),RangeError);for(const limit of[0,4097,1.2,Infinity])assert.throws(()=>M.facadePage(b,{limit}),RangeError);const end=M.facadePage(b,{cursor:M.facadePage(b).inventory.totalSlots,limit:1});assert.equal(end.done,true);assert.equal(end.openings.length,0);});
test('A page advances its bounded scan even when known openings occupy the procedural slots',()=>{const b=building('occupied',0,0,{rings:[[[0,0],[1000,0],[1000,16],[0,16],[0,0]]]});b.v050EntranceSelection=null;b.geoProperties.facadeDocument={...copy(documented),openings:[{type:'window',ringIndex:0,edgeIndex:0,offset:0,bottom:0,width:1000,height:12},{type:'window',ringIndex:0,edgeIndex:2,offset:0,bottom:0,width:1000,height:12}]};const all=allPages(b,1);assert.ok(all.pages>all.openings.length);assert.ok(all.openings.every(o=>o.provenance==='documented'||o.edgeIndex===1||o.edgeIndex===3));});
test('All ordinary facade/storey glazing is rendered before any ornamental allocation',()=>{const b=building(),g=M.geometry(b),p=M.facadePlan(b,{maxOpenings:307});assert.equal(g.openings,p.openings.length);assert.equal(g.description.detailCoverage.unrenderedPlannedOpenings,0);assert.equal(g.deferredOpenings.length,0);for(const maxQuads of[24,64,128]){const result=M.geometry(b,{maxQuads});assert.equal(result.description.detailCoverage.unrenderedPlannedOpenings,0);assert.ok(result.quads<=maxQuads);}});
test('Actual 84-segment IGN contour receives full-width curved doors and windows with source topology unchanged',()=>{const b=actualCurve(),before=copy(b),d=M.describe(b),es=M.edges(d),p=M.facadePlan(b),door=M.entrances(b)[0];assert.equal(d.sourceId,'batiment.9375075');assert.equal(es.length,84);assert.ok(es.every(e=>e.length<.317));assert.equal(p.openingInventory.curvedSurfaces,1);assert.equal(p.levels,2);assert.ok(door?.surfaceId);near(door.width,1.15);assert.ok(door.span.segments>=4);assert.equal(M.inside(d.rings,door.inside[0],door.inside[2]),true);assert.equal(M.inside(d.rings,door.outside[0],door.outside[2]),false);assert.ok(p.openings.some(o=>o.type==='window'&&o.surfaceId&&o.width>1));assert.deepEqual(b,before);});
test('Each curved base face follows its original source segment rather than a straight chord',()=>{const b=actualCurve(),g=M.geometry(b,{detail:'low'}),door=g.renderedOpenings.find(o=>o.type==='door'),spans=M.openingSpans(b,door),iron=g.draws.find(d=>d.id.endsWith(':iron'));assert.equal(spans.length,door.span.segments);near(spans.reduce((n,s)=>n+s.width,0),door.width);assert.equal(iron.faces.length,spans.length*2);const es=new Map(M.edges(M.describe(b)).map(e=>[e.edgeIndex,e]));for(let i=0;i<spans.length;i++){const span=spans[i],e=es.get(span.edgeIndex),v=iron.vertices.slice(i*4,i*4+4);near(v[0][0],e.a[0]+e.tangent[0]*span.offset+e.normal[0]*.027);near(v[0][2],e.a[1]+e.tangent[1]*span.offset+e.normal[1]*.027);near(v[1][0],e.a[0]+e.tangent[0]*(span.offset+span.width)+e.normal[0]*.027);near(v[1][2],e.a[1]+e.tangent[1]*(span.offset+span.width)+e.normal[1]*.027);}assert.equal(g.description.detailCoverage.unrenderedPlannedOpenings,0);assertOnSource(b,g);});
test('Curved facade identities and physical bays survive source winding/start changes',()=>{const a=actualCurve(),b=copy(a),ring=b.rings[0].slice(0,-1).reverse();b.rings=[ring.slice(27).concat(ring.slice(0,27))];b.rings[0].push(b.rings[0][0]);const da=M.entrances(a)[0],db=M.entrances(b)[0];assert.equal(da.id,db.id);for(let i=0;i<3;i++){near(da.center[i],db.center[i]);near(da.inside[i],db.inside[i]);near(da.outside[i],db.outside[i]);}const pa=allPages(a).openings,pb=allPages(b).openings;assert.equal(pa.length,pb.length);for(let i=0;i<pa.length;i++){assert.equal(pa[i].surfaceId,pb[i].surfaceId);near(pa[i].offset,pb[i].offset);near(pa[i].width,pb[i].width);near(pa[i].bottom,pb[i].bottom);}});
test('Curved entrance selected near another arc remains the exact physical interior08 doorway',()=>{const b=actualCurve(),d=M.describe(b),e=M.edges(d)[70],target=[(e.a[0]+e.b[0])/2+e.normal[0],(e.a[1]+e.b[1])/2+e.normal[1]],door=M.entrances(b,{near:target})[0];assert.notEqual(door.id,M.entrances(b)[0].id);b.v050EntranceSelection={...door,elevationOffset:3.8,levelElevations:[0,3.8]};const p=M.facadePlan(b),rendered=M.geometry(b).renderedOpenings.find(o=>o.type==='door');assert.equal(p.doors[0].id,door.id);assert.equal(rendered.surfaceId,door.surfaceId);assert.equal(rendered.edgeIndex,door.edgeIndex);near(rendered.offset,door.offset);near(rendered.bottom,3.8);assert.deepEqual(rendered.span,door.span);});
test('Documented raw edge indices remain exact inside a generated curved surface',()=>{const b=actualCurve(),opening={type:'window',ringIndex:0,edgeIndex:40,offset:.02,bottom:4.1,width:.08,height:.5};b.geoProperties.facadeDocument={...copy(documented),openings:[opening],completeEdges:[{ringIndex:0,edgeIndex:12}]};const page=allPages(b),known=page.openings.find(o=>o.provenance==='documented');assert.deepEqual(known,{...opening,provenance:'documented',source:documented.source});assert.deepEqual(M.openingSpans(b,known),[{ringIndex:0,edgeIndex:40,offset:.02,width:.08}]);for(const o of page.openings.filter(o=>o.provenance==='invented'))for(const span of M.openingSpans(b,o)){assert.notEqual(span.edgeIndex,12);if(span.edgeIndex===40)assert.equal(span.offset<.10&&span.offset+span.width>.02&&o.bottom<4.6&&o.bottom+o.height>4.1,false);}});
test('An attributed blind curved perimeter never gains an invented doorway or windows',()=>{const b=actualCurve();b.geoProperties.facadeDocument={...copy(documented),openings:[],completeEdges:Array.from({length:84},(_,edgeIndex)=>({ringIndex:0,edgeIndex}))};assert.equal(M.entrances(b).length,0);assert.equal(allPages(b).openings.length,0);});
test('Fragment budgets render a whole curved door or explicitly defer it without drawing a partial base',()=>{const b=actualCurve(),g=M.geometry(b,{maxQuads:8,detail:'low'}),door=g.renderedOpenings.find(o=>o.type==='door');assert.ok(door);const iron=g.draws.find(d=>d.id.endsWith(':iron'));assert.equal(iron.faces.length,M.openingSpans(b,door).length*2);assert.ok(g.deferredOpenings.length>0);assert.equal(g.description.detailCoverage.unrenderedPlannedOpenings,g.deferredOpenings.length);assert.ok(g.quads<=8);const ring=Array.from({length:8192},(_,i)=>[3*Math.cos(i/8192*Math.PI*2),3*Math.sin(i/8192*Math.PI*2)]);ring.push(ring[0]);const dense=building('dense',0,0,{height:7.6,rings:[ring],geoProperties:{}}),started=performance.now(),result=M.geometry(dense,{maxQuads:64});assert.ok(result.deferredOpenings.some(o=>o.type==='door'&&o.reason==='quad-budget'&&o.requiredQuads>64));assert.equal(result.renderedOpenings.some(o=>o.type==='door'),false);assert.equal(result.draws.some(d=>d.id.endsWith(':iron')),false);assert.ok(result.quads<=64);assert.ok(performance.now()-started<3000,'Dense source spans expanded before budgeting');assertOnSource(dense,result);});
function manyEdges(){const r=Array.from({length:100},(_,i)=>[100*Math.cos(i/100*Math.PI*2),100*Math.sin(i/100*Math.PI*2)]),a=r[0],b=r[1],len=Math.hypot(b[0]-a[0],b[1]-a[1]);r.splice(1,0,[a[0]+(b[0]-a[0])*2/len,a[1]+(b[1]-a[1])*2/len]);r.push(r[0]);return building('many-edges',0,0,{rings:[r]});}
test('Nearest bounded entrance search includes a short accessible edge outside the 64 longest',()=>{const b=manyEdges(),e=M.edges(M.describe(b))[0],near=[(e.a[0]+e.b[0])/2+e.normal[0]*1.15,(e.a[1]+e.b[1])/2+e.normal[1]*1.15],canonical=M.entrances(b),local=M.entrances(b,{near});assert.equal(canonical.length,64);assert.equal(canonical.some(o=>o.edgeIndex===0),false);assert.ok(local.some(o=>o.edgeIndex===0));assert.ok(local.length<=64);b.v050EntranceSelection=local.find(o=>o.edgeIndex===0);const p=M.facadePlan(b),g=M.geometry(b,{maxQuads:24});assert.equal(p.doors[0].id,b.v050EntranceSelection.id);assert.equal(g.renderedOpenings.find(o=>o.type==='door').edgeIndex,0);});
test('A short usable facade has one centred bay instead of losing all storeys below the normal bay spacing',()=>{const b=building('narrow',0,0,{rings:[[[0,0],[1.8,0],[1.8,8],[0,8],[0,0]]]});b.v050EntranceSelection=null;const page=allPages(b);for(const edgeIndex of[0,2]){const ws=page.openings.filter(o=>o.edgeIndex===edgeIndex);assert.equal(ws.length,4);for(const o of ws){near(o.offset+o.width/2,.9);assert.ok(o.offset>=.12&&o.offset+o.width<=1.68);}}});
test('Actual curved, square and hexagonal IGN facades below 1.6m retain actor-clearance-checked complete doors',()=>{const City=require('../../src/v050/08_city_interiors.js');for(const record of thresholdActualSources){assert.match(record.sha256,/^[a-f0-9]{64}$/);const b=copy(record.draw),before=copy(b),d=M.describe(b),descriptor=City.building(d),door=M.entrances(b).find(o=>City.clearance(descriptor.rings,o.inside[0]-descriptor.origin[0],o.inside[2]-descriptor.origin[2])>=.43);assert.equal(d.sourceId,record.sourceId);assert.ok(door,record.sourceId+' must have an actor-width accessible doorway');assert.ok(door.width>=.78-1e-7);assert.ok(door.height>=1.85);assert.equal(M.inside(d.rings,door.inside[0],door.inside[2]),true);assert.equal(M.inside(d.rings,door.outside[0],door.outside[2]),false);b.v050EntranceSelection=door;const g=M.geometry(b,{detail:'low'}),rendered=g.renderedOpenings.find(o=>o.type==='door'),spans=M.openingSpans(b,rendered),iron=g.draws.find(o=>o.id.endsWith(':iron'));assert.ok(rendered);assert.equal(rendered.edgeIndex,door.edgeIndex);near(rendered.offset,door.offset);near(rendered.width,door.width);near(spans.reduce((n,s)=>n+s.width,0),door.width);assert.equal(iron.faces.length,spans.length*2);assert.equal(g.deferredOpenings.length,0);assert.ok(g.quads<=512);if(record.sourceId==='batiment.9967526'){assert.ok(rendered.surfaceId);assert.equal(spans.length,10);assert.ok(M.curveSurfaces(d).some(c=>c.length>1.56&&c.length<1.57));}else assert.ok(M.edges(d).every(e=>e.length<1.6));assertOnSource(b,g);assert.deepEqual(b.rings,before.rings);assert.deepEqual(b.geoProperties,before.geoProperties);near(b.baseY,before.baseY);near(b.height,before.height);}});
test('The .78m doorway boundary follows its 60% facade width with only numerical tolerance',()=>{for(const width of[1.3,1.3-1e-8,1.3-1e-5]){const b=building('threshold',0,0,{rings:[[[0,0],[width,0],[width,8],[0,8],[0,0]]]}),doors=M.entrances(b),short=doors.filter(o=>o.edgeIndex===0||o.edgeIndex===2);assert.equal(short.length,width>=1.3-1e-7?2:0);for(const door of short){near(door.width,width*.6);assert.ok(door.width>=.78-1e-7);}}});
test('A selected documented door is recovered among more than 64 openings on the same source edge',()=>{const b=building('many-doors',0,0,{rings:[[[0,0],[1000,0],[1000,16],[0,16],[0,0]]]});b.geoProperties.facadeDocument={...copy(documented),openings:Array.from({length:100},(_,i)=>({type:'door',ringIndex:0,edgeIndex:0,offset:2+i*9,bottom:0,width:1.15,height:2.35}))};const selected=M.entrances(b,{near:[895,-1]})[0];assert.ok(selected.center[0]>890);b.v050EntranceSelection=selected;assert.equal(M.facadePlan(b).doors[0].id,selected.id);});

